import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from 'src/app/services/auth.service';
import { UIService } from 'src/app/services/ui.service';

@Component({
  selector: 'app-header',
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.css'],
})
export class HeaderComponent implements OnInit {
  user: any;
  constructor(private authService: AuthService, public uiService: UIService, private router: Router, ) {}
  @Output() menuToggle = new EventEmitter<void>();
  ngOnInit(): void {
    this.user = this.authService.getDecodedToken();

    console.log(this.user, '2234');
  }

  menuAberto = false; // Controla a visibilidade do menu


  onMenuClick() {
    this.menuToggle.emit();
  }

  logout() {
    alert("chegou aqui")
    this.router.navigate(['/login']);
    //this.loginService.clearSession();
  }
  toggleMenu() {

    this.menuAberto = !this.menuAberto;
  }
}
<header *ngIf="uiService.uiControlsVisibility | async">
  <div class="IconView">
    <div class="SearchContainer">
      <img src="assets/icone/Search.png" class="SearchIcon" />
      <input type="text" class="SearchInput" placeholder="Buscar" />
    </div>
  </div>

  <div class="MetaView">
    <div class="LastIcon">
      <img class="w-icone" src="assets/icone/notification.svg" (click)="onMenuClick()" />

      <!-- Ícone do usuário (clicável) -->
      <div class="user-container" (click)="toggleMenu()">
        <img class="user-icon" src="assets/icone/logout.svg"  />

      </div>

      <!-- Dropdown do menu -->
      <div class="dropdown-menu" *ngIf="menuAberto">
        <p class="name">{{ user.name }}</p>
        <button  (click)="logout()">Sair</button>
      </div>
    </div>
  </div>
</header>
